with filtered as (select *, round(discount / amount, 2) as discount_per_amount, coalesce(channel, 'OTHER') as resolved_channel from orders where order_date > date '2023-06-21' and store_id is not null) select channel, case when discount_per_amount >= 66 then 'LARGE' else 'SMALL' end as discount_per_amount_tier, max(discount) filter (where channel = 'partner') as partner_max_discount, round(sum(discount_per_amount) / nullif(count(case when channel = 'store' then 1 end), 0), 2) as discount_per_amount_per_store, size(collect_set(channel)) as num_channels, percent_rank() over (partition by channel order by max(discount) filter (where channel = 'partner') desc) as partner_max_discount_percent_rank from filtered group by channel, discount_per_amount_tier
